/* eslint-disable */
import React, { useRef, useState } from "react";
// Import de Link est retiré car react-router-dom n'est pas disponible dans l'environnement mono-fichier.

// --- Assets et Constantes (Remplacés par des placeholders URL pour l'exécution) ---
const placeholderImage = 'https://placehold.co/100x100/25509d/ffffff?text=IMG';
const AccelLogoLight = 'https://placehold.co/160x64/FFFFFF/1e204a?text=Accel+Logo';

const HeroImage = 'https://placehold.co/1920x860/A00000/ffffff?text=Hero+Background';
const BannerImage = 'https://placehold.co/1920x500/1C58C9/ffffff?text=Banner+Image';
const ressourcesImg = 'https://placehold.co/500x350/25509d/ffffff?text=Ressources+Portail';
const News1 = 'https://placehold.co/300x200/999999/ffffff?text=News+1';
const News2 = 'https://placehold.co/300x200/999999/ffffff?text=News+2';
const News3 = 'https://placehold.co/300x200/999999/ffffff?text=News+3';
const site1_baobab = 'https://placehold.co/400x120/4B7B49/ffffff?text=Baobab+Site';
const accel_png = 'https://placehold.co/400x120/25509d/ffffff?text=Data+Map+Site';
const shirikia_png = 'https://placehold.co/400x120/E8A02A/ffffff?text=Shirikia+Site';
const seynabou = 'https://placehold.co/100x100/D0D0D0/333333?text=SND';
const tamsir = 'https://placehold.co/100x100/D0D0D0/333333?text=TND';
const ndeye = 'https://placehold.co/100x100/D0D0D0/333333?text=NSN';
const sankara = 'https://placehold.co/150x150/007A33/ffffff?text=Sankara';
const ChatbotIcon = 'https://placehold.co/64x64/25509d/ffffff?text=Alex';
const birthday = 'https://placehold.co/48x48/F4B400/ffffff?text=🎂';

// --- Composants Intégrés ---

const IndexNavbar = () => (
  <nav className="fixed w-full z-30 bg-white shadow-lg">
    <div className="container mx-auto px-4 flex justify-between items-center py-4">
      <div className="text-xl font-extrabold text-[#20264e] tracking-wider">PORTAIL ACCUEIL</div>
      <div className="flex space-x-6 text-base font-medium">
        <a href="#accueil" className="text-[#25509d] hover:text-[#1e204a] transition-colors">Accueil</a>
        <a href="#actualites" className="text-[#25509d] hover:text-[#1e204a] transition-colors">Actualités</a>
        <a href="#sites" className="text-[#25509d] hover:text-[#1e204a] transition-colors">Sites</a>
        <a href="#contact" className="text-[#25509d] hover:text-[#1e204a] transition-colors">Contact</a>
      </div>
    </div>
  </nav>
);

const NewsCard = ({ img, title, date = '08 Octobre 2025', href = '#' }) => (
  <a href={href} className="flex items-center space-x-4 p-3 bg-white hover:bg-blue-50/50 rounded-xl transition duration-200 shadow-lg border border-blueGray-100">
    <div className="flex-shrink-0 w-24 h-20 overflow-hidden rounded-lg">
      <img src={img} alt={title} className="w-full h-full object-cover" onError={(e) => { e.target.onerror = null; e.target.src = placeholderImage; }} />
    </div>
    <div className="flex-1 min-w-0">
      <p className="text-xs font-semibold uppercase text-[#1c58c9] mb-1">{date}</p>
      <h4 className="text-sm font-extrabold text-gray-900 truncate">{title}</h4>
      <p className="text-xs text-gray-500 mt-1">Cliquez pour lire...</p>
    </div>
  </a>
);

const NewsStack = ({ items }) => {
  const newsData = items.map((item, index) => ({
    ...item,
    title: index === 0 ? "Le New Deal pour l'Afrique" : index === 1 ? "SIM Senegal 2025" : "Formation Mbaye - Réussie !",
  }));

  return (
    <div className="flex flex-col space-y-4">
      {newsData.map((item, index) => (
        <NewsCard key={index} img={item.img} title={item.title} href={item.href} />
      ))}
    </div>
  );
};

const PrettyCalendar = () => {
  // Simple monthly calendar view
  const days = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
  const today = new Date();
  const date = today.getDate();
  const month = today.toLocaleString('fr-FR', { month: 'long' });
  const year = today.getFullYear();

  return (
    <div className="bg-white p-4 rounded-xl shadow-2xl border border-blueGray-100">
      <div className="flex justify-between items-center mb-4 text-[#20264e]">
        <h4 className="font-bold text-lg capitalize">{month} {year}</h4>
        <div className="flex space-x-2 text-xl">
          <button aria-label="Mois précédent" className="text-gray-400 hover:text-[#25509d] transition-colors">
            <i className="fas fa-chevron-left text-sm"></i>
          </button>
          <button aria-label="Mois suivant" className="text-gray-400 hover:text-[#25509d] transition-colors">
            <i className="fas fa-chevron-right text-sm"></i>
          </button>
        </div>
      </div>
      <div className="grid grid-cols-7 gap-1 text-center text-sm">
        {days.map(d => (
          <div key={d} className="font-semibold text-gray-500">{d}</div>
        ))}
        {/* Jours du mois (Exemple du 1er au 28) */}
        {[...Array(32)].map((_, i) => {
          const dayNum = i - 3;
          const isCurrentDay = dayNum === date;
          const isEventDay = dayNum === 15 || dayNum === 22; // Placeholder for events
          return (
            <div
              key={i}
              className={`p-1 h-8 w-8 flex items-center justify-center mx-auto rounded-full cursor-pointer transition-all ${isCurrentDay ? 'bg-[#25509d] text-white font-bold shadow-md ring-2 ring-[#25509d]/30' :
                  isEventDay ? 'bg-fuchsia-100 text-[#25509d] font-semibold hover:bg-fuchsia-200' :
                    dayNum > 0 && dayNum < 29 ? 'text-gray-700 hover:bg-blueGray-100' : 'text-gray-400'
                }`}
            >
              {dayNum > 0 && dayNum < 29 ? dayNum : ''}
            </div>
          );
        })}
      </div>
    </div>
  );
};

